def build_bedbord():
    body=product_hero('Bedbord','A clearer picture.<br>A more personal<br>bedside.','Replace the handwritten whiteboard with a digital bedside display that makes important information easier to see, and the person easier to know.')
    body+='''<nav class="subnav" aria-label="Bedbord sections"><div class="container"><a href="#benefits">Why Bedbord</a><a href="#comparison">Whiteboard vs digital</a><a href="#person">What matters to me</a><a href="#value">Time & value</a><a href="#questions">Your questions</a></div></nav>
<section class="section" id="benefits"><div class="container"><div class="section-heading"><div><p class="eyebrow">From a task to a useful conversation</p><h2>Less rewriting.<br>More understanding.</h2></div><p>A whiteboard is only useful when it is readable and up to date. Bedbord gives teams a different way to approach that daily work.</p></div><div class="four-grid">'''+feature('eye','Clarity at a glance','A consistent, legible layout gives useful bedside information a clear home, without fading marker or smudged handwriting.')+feature('time','Time back for care','Explore how digital updates could reduce time spent erasing and rewriting boards. Measure the difference in your own setting.')+feature('person','The person, made visible','Make space for preferences, interests and “what matters to me”, alongside agreed bedside information.')+feature('leaf','Rethink consumables','Reduce reliance on board markers and paper labels. Assess this alongside device energy, hardware life and disposal.')+'''</div></div></section>
<section class="section ivory" id="comparison"><div class="container"><p class="eyebrow">A practical comparison</p><h2>Keep the purpose.<br>Change the board.</h2><div class="table-scroll"><table class="comparison"><caption class="small" style="text-align:left;margin-bottom:20px">Compare the everyday workflow. Final Bedbord features and integrations are agreed for your deployment.</caption><thead><tr><th scope="col">At the bedside</th><th scope="col">Traditional whiteboard</th><th scope="col">With Bedbord</th></tr></thead><tbody><tr><td>Readability</td><td>Depends on handwriting, marker condition and available space.</td><td>A consistent digital layout with clear text and structured sections.</td></tr><tr><td>Updating information</td><td>Erase, rewrite and check each board.</td><td>Digital updates; connected workflows subject to local integration and validation.</td></tr><tr><td>Knowing the person</td><td>Limited space for interests and preferences.</td><td>Dedicated room for what matters to the person.</td></tr><tr><td>Materials & upkeep</td><td>Markers, board erasers and replacement labels.</td><td>Less need for writing consumables; the display still needs approved cleaning.</td></tr><tr><td>Operational needs</td><td>Works without power or a network.</td><td>Requires power, appropriate connectivity and an agreed downtime process.</td></tr><tr><td>Information safety</td><td>Manual checks and local privacy practices.</td><td>Agreed visibility, update responsibilities and checks for stale or incorrect information.</td></tr></tbody></table></div><p class="note">A digital display supports communication. Staff must still verify identity and clinical information using the organisation’s approved records and procedures.</p></div></section>
<section class="section" id="person"><div class="container split"><div><p class="eyebrow">What matters to me</p><h2>See the individual.<br>Start a conversation.</h2><p class="lead">“Please call me Janie.”<br>“I love being in my garden.”</p><p>Small details can open the door to more personal care. Bedbord makes room for preferences and familiar interests so the person is present in the conversation.</p><ul class="check-list"><li>Preferred name and communication preferences</li><li>Personal interests and what matters today</li><li>Locally agreed information and daily goals</li></ul><p class="small">Display only information agreed with the person and care team. Photos and personal details need appropriate permission and visibility controls.</p></div><div><img class="split-image" src="assets/bedbord-screen.webp" alt="Illustrative Bedbord interface with patient information and a What Matters to Me section" width="1000" height="580" loading="lazy"><p class="photo-note">Illustrative interface. Configuration and available features are confirmed during discovery.</p></div></div></section>
<section class="section mint" id="value"><div class="container split"><div><p class="eyebrow">Make a measured decision</p><h2>What could a few<br>minutes give back?</h2><p>Use your own bed count and daily board-maintenance time to estimate hours that could be released. Add staffing costs and a supplier quote to explore a first-year business case.</p><p>Count only avoidable erasing and rewriting. Device cleaning and clinical verification remain part of safe care.</p>'''+button('Explore the time & ROI calculator','roi-calculator.html')+'''</div><div class="stat-box"><p class="eyebrow">An illustrative starting point</p><div class="number">730 hours</div><p>per year if a 24-bed ward saves 5 minutes per occupied bed, per day, at 100% occupancy.</p><p class="small">24 × 5 × 365 ÷ 60. An example calculation, not a measured TruSelv result or a promise of savings.</p></div></div></section>
<section class="section"><div class="container"><div class="section-heading"><div><p class="eyebrow">From discovery to a considered pilot</p><h2>Designed to fit your setting.</h2></div></div><div class="three-grid">'''+feature('chat','Start with the workflow','Look at how your team updates boards today, who uses the information and where the friction is.')+feature('shield','Agree the safeguards','Review information governance, display placement, clinical safety, cleaning and downtime arrangements.')+feature('board','Test what changes','Agree a small pilot, train the team and compare readability, maintenance time and user feedback.')+'''</div><div class="actions">'''+textlink('Download the Bedbord brief','downloads/bedbord-product-brief.pdf')+textlink('Review our safety approach','safety.html')+'''</div></div></section><section class="section ivory" id="questions"><div class="container narrow"><p class="eyebrow">Good questions</p><h2>Before you change the board.</h2>'''+faq([
('Does Bedbord automatically connect to our records system?','Integration depends on your records system, available interfaces and local approvals. Discovery establishes what can be connected and how data will be validated. We do not promise universal plug-and-play integration.'),
('Does a digital board still need cleaning?','Yes. The display and any touch surfaces still need cleaning using the approved device instructions and your infection prevention policy. The time calculator concerns avoidable board writing and erasing, not essential hygiene.'),
('Can Bedbord replace the clinical record?','No. Bedbord is a communication display. Use your approved clinical record, patient identity checks and local escalation procedures for clinical decisions.'),
('What happens if power or connectivity is lost?','Agree a local fallback before use. Staff need to know when information is unavailable or stale and return to approved records and communication processes. Ask for the release-specific downtime behaviour during assessment.'),
('How much does Bedbord cost?','We quote for your setting, device requirements, installation, software and any integration. Book a demonstration to start a scoped conversation.')])+'''</div></section>'''+cta('A more connected bedside<br>starts with a conversation.','Tell us about your ward, care home or care organisation.')
    page('bedbord.html','Bedbord — a clearer, more personal bedside','Explore the digital alternative to bedside whiteboards: clearer information, personal preferences and a practical time-saving calculator.',body)

def store_badge(kind):
    apple=kind=='apple'
    url=CONFIG['appStoreUrl' if apple else 'playStoreUrl'] or ('contact.html?topic='+quote('TESS '+('iPad' if apple else 'Android')+' app availability'))
    mark='<path d="M22 17c0-4 3-6 3-6-2-3-5-3-6-3-3 0-4 2-6 2S9 8 7 8C2 8 0 13 1 18c1 5 4 12 7 12 2 0 3-2 6-2 2 0 3 2 5 2 3 0 6-7 7-9-3-1-4-4-4-4ZM19 1c-3 0-6 4-5 7 3 0 6-3 5-7Z"/>' if apple else '<path d="M4 2v28l22-14Z" fill="none" stroke="currentColor" stroke-width="2"/><path d="m4 2 15 20M4 30 19 10" fill="none" stroke="currentColor" stroke-width="1.5"/>'
    return f'<a class="store-badge" href="{E(url)}"><svg viewBox="0 0 32 32" aria-hidden="true">{mark}</svg><span><small>{"Download on" if CONFIG["appStoreUrl" if apple else "playStoreUrl"] else "Ask about availability on"}</small><strong>{"App Store" if apple else "Google Play"}</strong></span></a>'

def build_tess():
    body=product_hero('TESS','More moments<br>that matter.','Communication, entertainment and meaningful engagement, together in one welcoming tablet experience. Meet the Therapeutic Engagement and Support System.')
    body+='''<nav class="subnav" aria-label="TESS sections"><div class="container"><a href="#benefits">Made for meaningful moments</a><a href="#activities">Explore the activities</a><a href="#tablet">The TESS tablet</a><a href="#download">Get the app</a><a href="#questions">Your questions</a></div></nav>
<section class="section" id="benefits"><div class="container split"><div><p class="eyebrow">Care is personal. So is connection.</p><h2>A little curiosity.<br>A familiar favourite.<br>A moment together.</h2><p class="lead">TESS brings more starting points for the moments that make a day feel like your own.</p><p>From a song that brings back a memory to a game shared with a visitor, TESS helps residents, families and care teams explore activities together.</p><p>Choose touch, a keyboard, a mouse or a stylus to find a comfortable way to take part, using compatible accessories.</p></div><div><img class="split-image" src="assets/tess-interaction_closeup.webp" alt="An older adult pointing at a TESS tablet with a care worker alongside" width="700" height="700" loading="lazy"><p class="photo-note">Illustrative care-setting imagery.</p></div></div></section>
<section class="section ivory" id="activities"><div class="container"><div class="section-heading"><div><p class="eyebrow">Follow what interests you</p><h2>Different ways to connect.<br>One place to begin.</h2></div><p>Explore the available activities in a demo. Features, content and compatibility vary by app release and plan.</p></div><div class="three-grid">'''+feature('chat','Conversation & AI chat','Prompts and conversation to explore together. AI can get things wrong; use it for engagement, never as clinical advice.')+feature('hand','Communication & signs','Explore communication tools and sign-based activities with support suited to the person. These do not replace a qualified interpreter.')+feature('game','Games & discovery','Choose an activity that matches the person’s interests, energy and preferences. Enjoy taking part without pressure to perform.')+feature('sun','Reminiscence','Make room for familiar subjects, shared stories and the experiences that matter to someone.')+feature('music','Radio & entertainment','Listen, watch and share favourites. Available services depend on connectivity, location and any third-party accounts or licences.')+feature('connect','Shared participation','Use TESS alongside the person, a family member or an activity coordinator. Let their choices lead the experience.')+'''</div></div></section>
<section class="section" id="tablet"><div class="container split"><img class="split-image" src="assets/tess-angled_bundle.webp" alt="TESS tablet displayed at an angle with keyboard, mouse and stylus" width="720" height="720" loading="lazy"><div><p class="eyebrow">A simple way to get started</p><h2>Your TESS tablet.<br>More ways to connect.</h2><div class="shop-price">£119</div><p>One tablet. More moments of connection.</p><ul class="check-list"><li>A dedicated tablet for the TESS experience</li><li>Activities for communication and engagement</li><li>Shared or supported use in care settings</li></ul><p class="small">'''+E(CONFIG['bundleStatement'])+'''</p><div class="actions">'''+button('Buy TESS','shop.html')+textlink('Book a demo','book-demo.html?product=TESS')+'''</div><p class="small" style="margin-top:20px">'''+E(CONFIG['vatStatement']+' '+CONFIG['deliveryStatement'])+'''</p></div></div></section>
<section class="section dark" id="download"><div class="container split"><div><p class="eyebrow">Already have a tablet?</p><h2>Make room for TESS<br>on your own device.</h2><p class="lead">The app is intended for compatible iPad and Android tablets, with a free download.</p><p>Check availability and device requirements with us. Ask us which features are available for your device.</p></div><div>'''+store_badge('apple')+store_badge('google')+'''<p class="small" style="margin-top:22px">Store listings and minimum operating-system requirements have not yet been published on this website. The links above help you ask about the right version for your device.</p></div></div></section>
<section class="section" id="questions"><div class="container narrow"><p class="eyebrow">A little more detail</p><h2>Your TESS questions.</h2>'''+faq([
('What is included in the £119 offer?','One TESS tablet. The photos show a keyboard, mouse, stylus, case and cable; the final accessory bundle and hardware specification will be confirmed before payment.'),
('Is TESS a medical treatment?','TESS is presented here as an engagement and communication experience. We do not claim it diagnoses, treats or prevents any condition. Activities should be chosen around individual preferences and support needs.'),
('Can we use TESS in a care home?','TESS is designed with shared and supported use in care settings in mind. Ask us about device management, hygiene instructions, account permissions and shared-device use before ordering for your organisation.'),
('Can I try it before buying?','Yes—request a free demonstration and tell us who will be using TESS. We can discuss the activities, interaction options and requirements relevant to your setting.'),
('Do I need an internet connection?','Online features, downloads and streaming require a suitable internet connection. Ask us to confirm any offline activities in the current app release.')])+'''<div class="actions">'''+textlink('Download the TESS product brief','downloads/tess-product-brief.pdf')+'''</div></div></section>'''+cta('Let’s find your<br>next shared moment.','See TESS with your residents, patients or family in mind.')
    page('tess.html','TESS — more moments that matter','Explore the TESS tablet: communication, games, reminiscence, radio and entertainment. £119.',body)

def field(name,label,typ='text',required=True,extra='',full=False):
    return f'<div class="field {"full" if full else ""}"><label for="{name}">{label}{"" if required else " <span class=muted>(optional)</span>"}</label><input type="{typ}" name="{name}" id="{name}" {"required" if required else ""} {extra}></div>'

def select(name,label,values,required=True):
    return f'<div class="field"><label for="{name}">{label}</label><select name="{name}" id="{name}" {"required" if required else ""}><option value="">Select an option</option>'+''.join(f'<option>{E(x)}</option>' for x in values)+'</select></div>'

def form(kind='demo'):
    demo=kind=='demo'
    heading='Let’s arrange your demo.' if demo else 'How can we help?'
    fields=field('name','Full name',extra='autocomplete="name" minlength="2" maxlength="100"')+field('email','Work or personal email','email',extra='autocomplete="email" maxlength="254"')
    if demo:
        fields+=field('organisation','Organisation / care setting',extra='autocomplete="organization" maxlength="150"')+field('postcode','Postcode or ODS code',required=False,extra='maxlength="30"')+select('role','Role / job title',['Nurse / clinical professional','Care home manager','Activities / wellbeing team','Digital / IT team','Procurement / leadership','Family member / individual','Other'])+select('product','Product of interest',['Bedbord','TESS','Both products'])
    else:
        fields+=select('topic','Enquiry type',['General enquiry','Product support','TESS app availability','Partnership','Privacy request','Accessibility request','Safety concern','Order / return'])+field('organisation','Organisation',required=False,extra='autocomplete="organization" maxlength="150"')
    fields+=f'<div class="field full"><label for="message">{"What would you like to explore?" if demo else "Your message"}</label><textarea id="message" name="message" rows="4" minlength="10" maxlength="3000" required placeholder="Tell us a little about your setting and what you need."></textarea><p class="form-hint">Please do not include patient details, medical records or other sensitive information.</p></div>'
    if demo: fields+=field('source','Where did you hear about us?',required=False,extra='maxlength="150"',full=True)
    return f'''<div class="form-panel"><h2>{heading}</h2><p class="small">{'A free product conversation, tailored to your setting. We will agree a time with you by email.' if demo else 'For urgent care needs, use your care provider’s usual contact route.'}</p><form data-inquiry="{kind}"><div class="form-grid">{fields}</div><div class="honeypot" aria-hidden="true"><label for="website">Leave this empty</label><input name="website" id="website" tabindex="-1" autocomplete="off"></div><label class="checkbox"><input type="checkbox" name="privacy" required><span>I have read the <a href="privacy.html">privacy notice</a> and understand how my enquiry will be handled.</span></label><button class="btn" type="submit" data-form-submit>Prepare {'demo request' if demo else 'enquiry'}</button><p class="form-hint" data-form-delivery>Review your request, then send it using your email app. No booking is made until we confirm a time.</p><p class="error-message" role="alert" hidden></p><div class="form-result" role="status" hidden></div></form><noscript><p class="no-js">Please email <a href="mailto:{CONFIG['email']}">{CONFIG['email']}</a> with your name, product of interest and a short message.</p></noscript></div>'''

def build_contact():
    body=hero('Let’s make care feel more human','See it. Ask questions.<br>Find your fit.','Book a free demonstration of Bedbord, TESS or both. Tell us what matters in your setting and we’ll start there.')
    body+='<section class="section"><div class="container form-layout"><div><p class="eyebrow">A conversation, built around you</p><h2>A useful first step.</h2><ol class="step-list"><li><h3>Tell us about your setting</h3><p>Your people, your current workflow and what you would like to explore.</p></li><li><h3>See the product in context</h3><p>Discuss the features, interaction options and practical requirements.</p></li><li><h3>Choose what comes next</h3><p>A product question, a tailored quote or a scoped pilot. There’s no obligation to purchase.</p></li></ol><div class="contact-item"><h3>Prefer to email?</h3><a href="mailto:'+CONFIG['email']+'">'+CONFIG['email']+'</a></div></div>'+form()+'</div></section>'
